INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (1, '旺旺 雪饼+仙贝 办公零食膨化休闲食品酥脆米果点心袋装', 'http://localhost:9090/files/download/1787547021486-2.png', 16.88, '旺旺雪饼和旺旺仙贝是孩子超爱吃的零食，奶香味浓郁，一口就爱上😋 家庭装实在划算，分量满满，吃起来完全不用担心不够～📦 物流很快，包装完好无损，品质没得挑👍 下次还会继续回购！🌟🌟', '<p><img src=\"http://localhost:9090/files/download/1787547073657-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/><img src=\"http://localhost:9090/files/download/1787547096378-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p>', 994, 1, '上架', 0, 76, '2026-08-24 12:51:40', '否');
INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (2, '无加蔗糖沙琪玛坚果山药沙琪玛木糖醇代餐充饥休闲零食食品 山药坚果沙琪玛', 'http://localhost:9090/files/download/1787547154113-1.png', 19.88, '货很迅速，店家很讲信誉，还会再来的，宝贝和介绍的一样，价格公道\n', '<p><img src=\"http://localhost:9090/files/download/1787547221744-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/><img src=\"http://localhost:9090/files/download/1787547241288-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p>', 500, 1, '上架', 0, 16, '2026-08-24 12:54:06', '否');
INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (3, 'ZHOUNDLEE周和利松露形巧克力比利时原装进口纯可可黑巧休息零食节日礼物 松露形巧克力', 'http://localhost:9090/files/download/1787547661139-3.png', 29.90, '比利时巧克力，很好吃，称得上极品！口感奶香味浓，入口即化，好吃😋,浓郁细腻无颗粒，甜度适中!!!', '<p><img src=\"http://localhost:9090/files/download/1787547741662-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/><img src=\"http://localhost:9090/files/download/1787547763011-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p>', 665, 6, '上架', 0, 66, '2026-08-24 13:02:47', '是');
INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (4, '三顿半快饮系列速溶冻干咖啡美式即溶纯黑咖啡粉 ', 'http://localhost:9090/files/download/1787676349172-4.png', 32.00, '三顿半美式黑咖啡味道口感不错，冲泡溶解也很快，每个都是独立包装出门携带很方便，送的玻璃杯质量也很好，像我们上班族每日一杯咖啡是必不可少的，提神醒脑促进代谢', '<p><img src=\"http://localhost:9090/files/download/1787676418121-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p><p><img src=\"http://localhost:9090/files/download/1787676428729-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p>', 454, 7, '上架', 0, 54, '2026-08-26 00:47:14', '否');
INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (5, '漫花山茶花大包抽纸纸巾大尺寸餐巾纸面巾纸擦手家用卫生纸原木纸抽纸 山茶花抽纸', 'http://localhost:9090/files/download/1787676471973-5.png', 26.90, '这纸性价比很高，湿水使用效果很好，材质安全放心，不容易分层，纸张够厚实 产品质量：很好，纸张很厚实 产品包装：包装精美，有质感 香味：香味比较淡 印花：很美精致', '<p><br></p><p><img src=\"http://localhost:9090/files/download/1787676511788-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/><img src=\"http://localhost:9090/files/download/1787676526733-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p>', 788, 9, '上架', 0, 12, '2026-08-26 00:49:10', '否');
INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (6, '娃哈哈 AD钙奶 含乳饮料  礼盒装 儿童回忆乳酸菌', 'http://localhost:9090/files/download/1787676689790-6.png', 1.80, '娃哈哈AD钙奶酸甜可口，口感清爽，喝起来很有童年回忆。优点在于价格亲民，包装方便携带，且含有钙和维生素A/D，营养健康。总体评价是一款性价比高的国民饮品，适合日常饮用，强烈推荐给喜欢怀旧风味的朋友。', '<p><img src=\"http://localhost:9090/files/download/1787676724306-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p><p><img src=\"http://localhost:9090/files/download/1787676736328-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p>', 647, 5, '上架', 0, 89, '2026-08-26 00:52:23', '是');
INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (7, '康师傅冰红茶冻冻茶 小马宝莉联名款 茶饮料', 'http://localhost:9090/files/download/1787676756205-7.png', 4.50, '冰箱里整整齐齐摆着几排饮料，阳光照进来，瓶身反光挺好看。味道层次确实丰富，酸甜平衡，喝起来很清爽，配料表也干净，没看到太多添加剂。快递包装严实，瓶子一个都没漏，送货快，配送员态度也好。整体体验很舒服，下次还会买 🌟🥤🥤', '<p><img src=\"http://localhost:9090/files/download/1787676840704-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p><p><img src=\"http://localhost:9090/files/download/1787676850564-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p>', 853, 5, '上架', 0, 27, '2026-08-26 00:54:16', '是');
INSERT INTO `goods` (`id`, `name`, `img`, `price`, `description`, `content`, `store`, `category_id`, `status`, `views`, `sale_count`, `time`, `recommend`) VALUES (8, '小米巨能写中性笔 10支装 黑色0.5mm 商务办公中性笔会议笔 黑色', 'http://localhost:9090/files/download/1787676935398-8.png', 1.50, '小米中性笔外观简约时尚，握感舒适长时间书写不累。墨水流畅不断墨，出墨均匀字迹清晰。价格实惠性价比高，是日常办公学习的好选择。', '<p><img src=\"http://localhost:9090/files/download/1787676973227-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p><p><img src=\"http://localhost:9090/files/download/1787676983179-image.png\" alt=\"\" data-href=\"\" style=\"width: 100%;\"/></p><p><br></p>', 757, 4, '上架', 0, 42, '2026-08-26 00:56:26', '是');
